22:public final class ClimateWriteResult implements Parcelable {
23:    public static final int ERROR_NONE = 0;
24:    public static final int ERROR_PERMISSION = 1;
25:    public static final int ERROR_UNAVAILABLE = 2;
26:    public static final int ERROR_INVALID_ARGUMENT = 3;
27:
28:    private final long requestId;
29:    private final boolean accepted;
30:    private final int errorCode;
31:    private final String message;
32:    private final long revision;
33:
34:    public ClimateWriteResult(long requestId, boolean accepted, int errorCode, String message, long revision) {
35:        this.requestId = requestId;
36:        this.accepted = accepted;
37:        this.errorCode = errorCode;
38:        this.message = message == null ? "" : message;
39:        this.revision = revision;
40:    }
41:
42:    private ClimateWriteResult(Parcel source) {
43:        requestId = source.readLong();
44:        accepted = source.readInt() != 0;
45:        errorCode = source.readInt();
46:        message = source.readString();
47:        revision = source.readLong();
48:    }
49:
50:    public long getRequestId() { return requestId; }
51:    public boolean isAccepted() { return accepted; }
52:    public int getErrorCode() { return errorCode; }
53:    public String getMessage() { return message; }
54:    public long getRevision() { return revision; }
55:
56:    @Override public int describeContents() { return 0; }
57:    @Override public void writeToParcel(Parcel destination, int flags) {
58:        destination.writeLong(requestId);
59:        destination.writeInt(accepted ? 1 : 0);
60:        destination.writeInt(errorCode);
61:        destination.writeString(message);
62:        destination.writeLong(revision);
63:    }
64:
65:    public static final Creator<ClimateWriteResult> CREATOR = new Creator<ClimateWriteResult>() {
66:        @Override public ClimateWriteResult createFromParcel(Parcel source) { return new ClimateWriteResult(source); }
67:        @Override public ClimateWriteResult[] newArray(int size) { return new ClimateWriteResult[size]; }
68:    };
69:}

